/* QuickBooks Online sync: bills and expenses (last 180 days) matched to hub jobs by job number in the line's
   customer/project, line description, memo or doc number. Inserts new costs and updates changed ones (amounts,
   date, supplier, ref). Category is set once on insert and then left to the office. */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>{const x=parseFloat(S(v));return isNaN(x)?0:x;};const r2=v=>Math.round(v*100)/100;
const list=async t=>{const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true,timeout:30000});return (Array.isArray(L)?L:[]).filter(r=>r&&r.id!=null);};
const save=(t,id,row,p)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t='+t+'&id='+(id||0)+'&k='+K+(p?'&partial=1':''),body:row,json:true,timeout:20000});
const del=(t,id)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=del&t='+t+'&id='+id+'&k='+K,body:{},json:true,timeout:20000});
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
async function status(o){try{const O=(await list('selectopts')).filter(x=>S(x.reg)==='jobcosts'&&S(x.field)==='qbo_sync');for(const x of O)await del('selectopts',x.id);await save('selectopts',0,{reg:'jobcosts',field:'qbo_sync',value:JSON.stringify(Object.assign({at:now},o)),added_by:'QuickBooks sync'});}catch(e){}}
const get=n=>{try{return $(n).all().map(i=>i.json);}catch(e){return [];}};
const B=get('QBO Bills'),P=get('QBO Purchases');
const errOf=a=>a.find(x=>x&&(x.error||x.message&&!x.Id));
const e1=errOf(B)||errOf(P);
const real=a=>a.filter(x=>x&&x.Id);
if(e1&&!real(B).length&&!real(P).length){const msg=/credential|auth|token|401|403|connect/i.test(JSON.stringify(e1))?'QuickBooks is not connected yet.':'QuickBooks returned an error: '+S(e1.message||e1.error).slice(0,200);await status({ok:false,message:msg});return [{json:{ok:false,message:msg}}];}
const J=await list('jobrows');const JOBS={};J.forEach(r=>{const k=jk(r.ref);if(k)JOBS[k]=S(r.ref);});
function findJob(){for(const t of arguments){const m=S(t).match(/\b\d{3,6}\b/g)||[];for(const x of m){if(JOBS[jk(x)])return JOBS[jk(x)];}}return '';}
function cat(acc,desc){const s=(S(acc)+' '+S(desc)).toLowerCase();if(/sub ?contract|cis\b/.test(s))return 'Subcontractors';if(/hire|plant|skip|scaffold/.test(s))return 'Plant hire';if(/labou?r|wages|agency/.test(s))return 'Labour';if(/material|supplies|timber|stock|cost of sales|cogs|purchases/.test(s))return 'Materials';return 'Other';}
const out={};let unmatched=0;
function take(kind,t){const vendor=S((t.VendorRef&&t.VendorRef.name)||(t.EntityRef&&t.EntityRef.name));const tot=num(t.TotalAmt),tax=num(t.TxnTaxDetail&&t.TxnTaxDetail.TotalTax);const netAll=tot-tax;
 (t.Line||[]).forEach(l=>{const d=l.AccountBasedExpenseLineDetail||l.ItemBasedExpenseLineDetail;if(!d)return;const cust=S(d.CustomerRef&&d.CustomerRef.name);
  const job=findJob(cust,l.Description,t.PrivateNote,t.DocNumber);if(!job){unmatched++;return;}
  const key=kind+':'+t.Id+':'+jk(job);const o=out[key]=out[key]||{qbo_id:key,job_no:job,cost_date:S(t.TxnDate),supplier:vendor,ref:S(t.DocNumber),net:0,acc:'',desc:[],kind:kind};
  o.net+=num(l.Amount);if(!o.acc)o.acc=S(d.AccountRef&&d.AccountRef.name)||S(d.ItemRef&&d.ItemRef.name);if(S(l.Description))o.desc.push(S(l.Description));});
 Object.keys(out).filter(k=>k.indexOf(kind+':'+t.Id+':')===0).forEach(k=>{const o=out[k];const share=netAll?o.net/netAll:0;o.vat=r2(tax*share);o.net=r2(o.net);o.gross=r2(o.net+o.vat);});}
real(B).forEach(t=>take('Bill',t));real(P).forEach(t=>take('Expense',t));
const C=await list('jobcosts');const have={};C.forEach(r=>{if(S(r.qbo_id))have[S(r.qbo_id)]=r;});
let added=0,updated=0;
for(const k of Object.keys(out)){const o=out[k];const row={job_no:o.job_no,cost_date:o.cost_date,supplier:o.supplier,ref:o.ref,net:o.net,vat:o.vat,gross:o.gross};
 const ex=have[k];
 if(ex){if(Number(ex.net)!==o.net||Number(ex.vat)!==o.vat||S(ex.cost_date)!==o.cost_date||S(ex.supplier)!==o.supplier||S(ex.ref)!==o.ref){row.history=[S(ex.history),now.slice(8,10)+'/'+now.slice(5,7)+'/'+now.slice(0,4)+' '+now.slice(11,16)+' - Updated from QuickBooks'].join(String.fromCharCode(10));await save('jobcosts',ex.id,row,true);updated++;}}
 else{Object.assign(row,{category:cat(o.acc,o.desc.join(' ')),description:o.desc.join('; ').slice(0,500)||(o.kind==='Bill'?'QuickBooks bill':'QuickBooks expense'),po_no:'',source:'QuickBooks',qbo_id:k,file_url:'',notes:'',created_by:'QuickBooks sync',created_at:now,history:now.slice(8,10)+'/'+now.slice(5,7)+'/'+now.slice(0,4)+' '+now.slice(11,16)+' - Added from QuickBooks '+o.kind.toLowerCase()});await save('jobcosts',0,row,false);added++;}}
const res={ok:true,bills:real(B).length,expenses:real(P).length,added:added,updated:updated,unmatched:unmatched,message:'Synced: '+added+' added, '+updated+' updated'+(unmatched?', '+unmatched+' lines with no job number':'')};
await status(res);return [{json:res}];
